package cloudsigma_test

import (
	"context"
	"encoding/json"
	"io"
	"net/http"
	"reflect"
	"strings"
	"testing"

	sdk "github.com/cloudsigma/cloudsigma-sdk-go/cloudsigma"
)

// Literal expectations follow the public autogenerated-keypair example.
// A decoded acknowledgment is not proof of installation on any server.
func TestKeygenPreparsePublicContract(t *testing.T) {
	for _, algorithm := range []string{"rsa", "ed25519"} {
		for _, code := range []int{200, 201, 202} {
			calls := 0
			input := &sdk.KeypairGenerateRequest{Name: "test_name", AlgorithmType: algorithm}
			before := *input
			c := sdk.NewClient(sdk.NewTokenCredentialsProvider("contract-token"), sdk.WithEndpoint("https://example.invalid/api/2.0/"), sdk.WithHTTPClient(&http.Client{Transport: resourceRedirectTransport(func(q *http.Request) (*http.Response, error) {
				calls++
				if q.Method != "POST" || q.URL.RequestURI() != "/api/2.0/keypairs/" || q.Header.Get("Authorization") != "Bearer contract-token" {
					t.Error("public route/auth changed")
				}
				var body map[string][]map[string]string
				if e := json.NewDecoder(q.Body).Decode(&body); e != nil {
					t.Fatal(e)
				}
				_ = q.Body.Close()
				want := map[string][]map[string]string{"objects": {{"name": "test_name", "algorithm_type": algorithm}}}
				if !reflect.DeepEqual(body, want) {
					t.Fatalf("documented payload changed: %#v", body)
				}
				return &http.Response{StatusCode: code, Header: make(http.Header), Body: io.NopCloser(strings.NewReader(`{"objects":[{"uuid":"key-ack","name":"test_name","private_key":"synthetic-private","public_key":"synthetic-public","fingerprint":"synthetic-fingerprint","resource_uri":"/api/2.0/keypairs/key-ack/"}]}`)), Request: q}, nil
			})}))
			v, r, e := c.Keypairs.Generate(context.Background(), input)
			if e != nil || r == nil || r.StatusCode != code || len(v) != 1 || calls != 1 || *input != before {
				t.Fatalf("acknowledgment changed: %v %v %v calls=%d", v, r, e, calls)
			}
			if v[0].UUID != "key-ack" || v[0].PrivateKey != "synthetic-private" || v[0].PublicKey != "synthetic-public" || v[0].Fingerprint != "synthetic-fingerprint" || v[0].ResourceURI != "/api/2.0/keypairs/key-ack/" {
				t.Fatal("decoded key acknowledgment changed")
			}
		}
	}
}
